#include <vector>

bool canJump(const std::vector<int>& nums) {
    int farthest = 0;  // the farthest index you can reach so far
    for (int i = 0; i < static_cast<int>(nums.size()); i++) {
        if (i > farthest) {
            return false;
        }
        farthest = std::max(farthest, i + nums[i]);
    }
    return true;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> nums(n);
    for (int i = 0; i < n; i++) {
        std::cin >> nums[i];
    }
    std::cout << (canJump(nums) ? "true" : "false") << "\n";
    return 0;
}

